def climb_stairs(n):
    cache = {}                   # Shared within this request.

    def solve(k):
        if k in cache:           # Look up before branching.
            return cache[k]
        if k < 2:
            result = 1
        else:
            result = solve(k - 1) + solve(k - 2)
        cache[k] = result        # Save before returning.
        return result

    return solve(n)
